toad_implementation.code_blueprint:
canvas {
  size: 800px 800px;
  fill: #050505;
  font-family: "JetBrains Mono, monospace";
}

>acidYellow = #E6FF00;
>hazardRed = #FF003C;
>rawWhite = #F2F2F2;

rect #outerFrame {
  at: center of canvas;
  size: 420px 420px;
  fill: none;
  stroke: >acidYellow;
  stroke-width: 6px;
}

rect #warningBlock {
  at: top left of #outerFrame offset 16px;
  size: 140px 32px;
  fill: >hazardRed;
}

text #warningText {
  at: center of #warningBlock;
  content: "HAZARD // 01";
  font-size: 13px;
  font-weight: 800;
  color: #050505;
}

rect #centerBlock {
  at: center of #outerFrame;
  size: 260px 140px;
  fill: >acidYellow;
}

text #hugeLogoText {
  at: center of #centerBlock;
  content: "RAW";
  font-size: 72px;
  font-weight: 900;
  color: #050505;
}

text #metadataFooter {
  at: below #outerFrame offset 32px;
  content: "[SYSTEM.DECONSTRUCTED // TOAD_V1]";
  font-size: 14px;
  font-weight: 700;
  color: >rawWhite;
}
